program.source:
Funcion tax <- Vat(price Como Entero)
  Definir tax Como Entero;
  Escribir "Computing the VAT";
  tax <- price * 21 div 100;
FinFuncion

Algoritmo Main
  Definir price Como Entero;
  Leer price;
  Escribir "VAT: ", Vat(price);
FinAlgoritmo

